<?php
require_once __DIR__.'/../includes/admin_layout.php'; $file=__DIR__.'/../data/offers.json';$rows=readJson($file);$edit=null;$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete'){$rows=array_values(array_filter($rows,fn($r)=>(int)$r['id']!==$id));writeJson($file,$rows);$msg='Offer deleted.';}elseif($action==='toggle'){foreach($rows as &$r)if((int)$r['id']===$id)$r['active']=!empty($r['active'])?false:true;unset($r);writeJson($file,$rows);$msg='Offer status updated.';}elseif($action==='save'){$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$old=(float)($_POST['old_price']??0);$disc=(float)($_POST['discount']??0);if(!$title)$msg='Title is required.';else{if($id){foreach($rows as &$r)if((int)$r['id']===$id){$r=['id'=>$id,'title'=>$title,'description'=>$desc,'price'=>$price,'old_price'=>$old,'discount'=>$disc,'active'=>isset($_POST['active'])];break;}unset($r);}else{$rows[]=['id'=>nextId($rows),'title'=>$title,'description'=>$desc,'price'=>$price,'old_price'=>$old,'discount'=>$disc,'active'=>isset($_POST['active'])];}writeJson($file,$rows);header('Location: offers.php?msg=saved');exit;}}}if(isset($_GET['edit']))foreach($rows as $r)if((int)$r['id']===(int)$_GET['edit'])$edit=$r;if(isset($_GET['msg']))$msg='Offer saved successfully.';adminStart('Offers & Discounts','offers');if($msg):?><div class="notice success">✅ <?=h($msg)?></div><?php endif;?><div class="admin-two"><section class="admin-panel"><h2><?= $edit?'✏️ Edit Offer':'➕ Add Offer'?></h2><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($edit['id']??0)?>"><div class="form-group"><label>Title</label><input class="form-control" name="title" required value="<?=h($edit['title']??'')?>"></div><div class="form-group"><label>Description</label><textarea class="form-control" name="description"><?=h($edit['description']??'')?></textarea></div><div class="form-group"><label>Offer Price</label><input class="form-control" type="number" step="0.01" min="0" name="price" value="<?=h($edit['price']??0)?>"></div><div class="form-group"><label>Old Price</label><input class="form-control" type="number" step="0.01" min="0" name="old_price" value="<?=h($edit['old_price']??0)?>"></div><div class="form-group"><label>Discount %</label><input class="form-control" type="number" step="0.1" min="0" max="100" name="discount" value="<?=h($edit['discount']??0)?>"></div><label><input type="checkbox" name="active" <?=!empty($edit['active'])||!$edit?'checked':''?>> Active</label><br><br><button class="btn btn-primary">💾 Save Offer</button></form></section><section class="admin-panel"><h2>🏷️ Current Offers</h2><div class="table-wrap"><table><tr><th>Title</th><th>Price</th><th>Discount</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><b><?=h($r['title'])?></b><br><small><?=h($r['description'])?></small></td><td>₹<?=h($r['price'])?></td><td><?=h($r['discount'])?>%</td><td><?=!empty($r['active'])?'🟢 Active':'🔴 Inactive'?></td><td><a class="btn btn-secondary" href="offers.php?edit=<?=$r['id']?>">Edit</a><form method="post" style="display:inline"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn btn-primary">Toggle</button></form><form method="post" style="display:inline"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger" onclick="return confirm('Delete offer?')">Delete</button></form></td></tr><?php endforeach;?></table></div></section></div><?php adminEnd();?>